const files = <validategeneratedfiles.result.files>;
if (Number(<gettargetbranchtree.status>) !== 200 || !Array.isArray(<gettargetbranchtree.data.tree>)) {
  throw new Error('Не удалось прочитать актуальное дерево целевой ветки.');
}
const targetTree = new Map(<gettargetbranchtree.data.tree>.map((entry) => [String(entry.path ?? ''), entry]));

function utf8ToBase64(value) {
  const text = String(value ?? '');
  const bytes = [];

  for (let i = 0; i < text.length; i++) {
    let codePoint = text.charCodeAt(i);

    if (codePoint >= 0xd800 && codePoint <= 0xdbff) {
      const next = text.charCodeAt(i + 1);
      if (next >= 0xdc00 && next <= 0xdfff) {
        codePoint = 0x10000 + ((codePoint - 0xd800) << 10) + (next - 0xdc00);
        i++;
      } else {
        codePoint = 0xfffd;
      }
    } else if (codePoint >= 0xdc00 && codePoint <= 0xdfff) {
      codePoint = 0xfffd;
    }

    if (codePoint <= 0x7f) {
      bytes.push(codePoint);
    } else if (codePoint <= 0x7ff) {
      bytes.push(0xc0 | (codePoint >> 6));
      bytes.push(0x80 | (codePoint & 0x3f));
    } else if (codePoint <= 0xffff) {
      bytes.push(0xe0 | (codePoint >> 12));
      bytes.push(0x80 | ((codePoint >> 6) & 0x3f));
      bytes.push(0x80 | (codePoint & 0x3f));
    } else {
      bytes.push(0xf0 | (codePoint >> 18));
      bytes.push(0x80 | ((codePoint >> 12) & 0x3f));
      bytes.push(0x80 | ((codePoint >> 6) & 0x3f));
      bytes.push(0x80 | (codePoint & 0x3f));
    }
  }

  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let result = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const a = bytes[i];
    const hasB = i + 1 < bytes.length;
    const hasC = i + 2 < bytes.length;
    const b = hasB ? bytes[i + 1] : 0;
    const c = hasC ? bytes[i + 2] : 0;

    result += alphabet[a >> 2];
    result += alphabet[((a & 3) << 4) | (b >> 4)];
    result += hasB ? alphabet[((b & 15) << 2) | (c >> 6)] : '=';
    result += hasC ? alphabet[c & 63] : '=';
  }
  return result;
}

const prepared = files.map((f) => {
  const existing = targetTree.get(String(f.path ?? ''));
  return {
    ...f,
    exists: Boolean(existing),
    sha: String(existing?.sha ?? ''),
    content_base64: utf8ToBase64(f.content)
  };
});

return {
  create_files: prepared.filter((f) => !f.exists),
  update_files: prepared.filter((f) => f.exists)
};

return {
  status: 'invalid_repository_context',
  run_id: String(<validateimplementationinput.result.run_id> ?? ''),
  errors: Array.isArray(<buildrepositorycontext.result.errors>)
    ? <buildrepositorycontext.result.errors>
    : []
};

const decision = String(<codeapproval.decision> ?? '').trim().toLowerCase();
const comments = String(<codeapproval.comments> ?? '').trim();
const allowed = ['approve', 'revise', 'reject'];
const commentsRequired = decision === 'revise' || decision === 'reject';
const valid = allowed.includes(decision) && (!commentsRequired || comments.length > 0);

return {
  decision,
  comments,
  valid,
  error: !allowed.includes(decision)
    ? 'Допустимы только approve, revise или reject.'
    : commentsRequired && !comments
      ? 'Для revise или reject необходим комментарий.'
      : ''
};

return {
  status: 'invalid_tree_context',
  run_id: String(<validateimplementationinput.result.run_id> ?? ''),
  errors: Array.isArray(<selectcontextpaths.result.errors>)
    ? <selectcontextpaths.result.errors>
    : []
};

const generated = <developer.files>;
const artifact = <validateimplementationinput.result.artifact>;
const treeEntries = <selectcontextpaths.result.tree_entries>;
const contextFiles = <buildrepositorycontext.result.files>;
const profile = artifact?.implementation_profile ?? {};

const planFiles = Array.isArray(artifact?.repository_plan?.files)
  ? artifact.repository_plan.files
  : [];

const plan = new Map(
  planFiles.map((file) => [String(file.path ?? ''), file])
);

const tree = new Map(
  (Array.isArray(treeEntries) ? treeEntries : []).map(
    (entry) => [String(entry.path ?? ''), entry]
  )
);

const readContext = new Set(
  (Array.isArray(contextFiles) ? contextFiles : []).map(
    (file) => String(file.path ?? '')
  )
);

const errors = [];
const normalizationWarnings = [];
const seenLower = new Set();
const generatedExactPaths = new Set();

const forbiddenPrefixes = [
  '.git/',
  '.gitea/',
  '.github/',
  'ci/',
  'k8s/',
  'policies/',
  'secrets/',
  'vendor/',
  'node_modules/',
  'dist/',
  'build/',
  'artifacts/'
];

const forbiddenBasenames = new Set([
  '.env',
  '.env.local',
  'secrets.yaml',
  'secrets.yml',
  'id_rsa',
  'id_ed25519'
]);

const forbiddenSecretExtension = /\.(pem|key|p12|pfx)$/i;
const pathPattern =
  /^(?!\/)(?!.*\.\.)(?!.*\\)(?!.*\/\/)[A-Za-z0-9._/-]+$/;

const secretPatterns = [
  /-----BEGIN (RSA |EC |OPENSSH )?PRIVATE KEY-----/,
  /(?:password|token|api[_-]?key)\s*[:=]\s*['"][^'"]{8,}/i
];

const allowedEmptyBasenames = new Set(
  (Array.isArray(profile?.allowed_empty_basenames)
    ? profile.allowed_empty_basenames
    : []
  ).map((name) => String(name ?? '').toLowerCase())
);

const maxGeneratedFiles = Number(
  profile?.limits?.max_generated_files ?? 50
);

const maxFileChars = Number(
  profile?.limits?.max_file_chars ?? 200000
);

const maxPayloadChars = Number(
  profile?.limits?.max_payload_chars ?? 1000000
);

if (!Array.isArray(generated)) {
  errors.push('developer.files должен быть массивом');
}

let totalChars = 0;
const files = [];

for (const item of Array.isArray(generated) ? generated : []) {
  const path = String(item?.path ?? '').trim();
  const content = String(item?.content ?? '');
  const suppliedReason = String(item?.reason ?? '').trim();
  const plannedFile = plan.get(path);
  const plannedPurpose = String(plannedFile?.purpose ?? '').trim();
  const plannedRequirementIds = Array.isArray(
    plannedFile?.requirement_ids
  )
    ? plannedFile.requirement_ids
        .map((value) => String(value ?? '').trim())
        .filter(Boolean)
    : [];
  const fallbackReason = [
    plannedPurpose || 'Файл предусмотрен утверждённым repository plan',
    plannedRequirementIds.length > 0
      ? `Требования: ${plannedRequirementIds.join(', ')}`
      : ''
  ].filter(Boolean).join('. ');
  const reason = suppliedReason || fallbackReason;
  const lower = path.toLowerCase();
  const basename = lower.split('/').pop() ?? '';

  if (!pathPattern.test(path)) {
    errors.push(`Недопустимый path: ${path}`);
  }

  if (forbiddenPrefixes.some((prefix) => lower.startsWith(prefix))) {
    errors.push(`Запрещённый path: ${path}`);
  }

  if (
    forbiddenBasenames.has(basename) ||
    forbiddenSecretExtension.test(lower)
  ) {
    errors.push(`Запрещённый secret path: ${path}`);
  }

  if (!plan.has(path)) {
    errors.push(`Path отсутствует в approved repository plan: ${path}`);
  }

  if (seenLower.has(lower)) {
    errors.push(`Дублирующийся path: ${path}`);
  }

  seenLower.add(lower);
  generatedExactPaths.add(path);

  const emptyAllowed = allowedEmptyBasenames.has(basename);

  if (!content && !emptyAllowed) {
    errors.push(`Пустое содержимое запрещено: ${path}`);
  }

  if (content.length > maxFileChars) {
    errors.push(
      `Файл превышает лимит ${maxFileChars} символов: ${path}`
    );
  }

  if (/[\u3400-\u9fff]/u.test(content)) {
    errors.push(`Обнаружены китайские иероглифы в файле: ${path}`);
  }
  if (/<\/?think>/iu.test(content)) {
    errors.push(`Обнаружен think tag в файле: ${path}`);
  }

  if (!reason) {
    errors.push(`Не указан reason и его нельзя восстановить из plan: ${path}`);
  } else if (!suppliedReason) {
    normalizationWarnings.push(
      `Reason восстановлен из approved repository plan: ${path}`
    );
  }

  if (secretPatterns.some((pattern) => pattern.test(content))) {
    errors.push(`Возможный secret в содержимом: ${path}`);
  }

  totalChars += content.length;

  const existing = tree.get(path);

  if (existing && !readContext.has(path)) {
    errors.push(
      `Существующий файл не был прочитан перед изменением: ${path}`
    );
  }

  files.push({
    path,
    content,
    reason,
    exists: Boolean(existing),
    sha: String(existing?.sha ?? ''),
    encoded_path: path
      .split('/')
      .map(encodeURIComponent)
      .join('/')
  });
}

if (
  files.length < 1 ||
  files.length > maxGeneratedFiles
) {
  errors.push(
    `Нужно вернуть 1..${maxGeneratedFiles} файлов`
  );
}

if (totalChars > maxPayloadChars) {
  errors.push(
    `Общий payload превышает ${maxPayloadChars} символов`
  );
}

// Каждый planned файл, которого ещё нет в base branch,
// обязательно должен быть создан этой генерацией.
for (const planned of planFiles) {
  const path = String(planned?.path ?? '');

  if (!tree.has(path) && !generatedExactPaths.has(path)) {
    errors.push(
      `Не сгенерирован новый обязательный файл из plan: ${path}`
    );
  }
}

return {
  valid: errors.length === 0,
  errors,
  warnings: normalizationWarnings,
  files,
  file_paths: files.map((file) => file.path),
  total_chars: totalChars,
  summary: <developer.summary>,
  tests: <developer.tests>,
  risks: <developer.risks>
};

