function decodeUtf8(bytes) {
  let result = '';

  for (let i = 0; i < bytes.length;) {
    const first = bytes[i++];

    if (first <= 0x7f) {
      result += String.fromCharCode(first);
      continue;
    }

    let codePoint;
    let continuationCount;
    let minimumCodePoint;

    if ((first & 0xe0) === 0xc0) {
      codePoint = first & 0x1f;
      continuationCount = 1;
      minimumCodePoint = 0x80;
    } else if ((first & 0xf0) === 0xe0) {
      codePoint = first & 0x0f;
      continuationCount = 2;
      minimumCodePoint = 0x800;
    } else if ((first & 0xf8) === 0xf0) {
      codePoint = first & 0x07;
      continuationCount = 3;
      minimumCodePoint = 0x10000;
    } else {
      result += '\uFFFD';
      continue;
    }

    if (i + continuationCount > bytes.length) {
      result += '\uFFFD';
      break;
    }

    let valid = true;

    for (let j = 0; j < continuationCount; j++) {
      const next = bytes[i];

      if ((next & 0xc0) !== 0x80) {
        valid = false;
        break;
      }

      i++;
      codePoint = (codePoint << 6) | (next & 0x3f);
    }

    if (
      !valid ||
      codePoint < minimumCodePoint ||
      codePoint > 0x10ffff ||
      (codePoint >= 0xd800 && codePoint <= 0xdfff)
    ) {
      result += '\uFFFD';
      continue;
    }

    if (codePoint <= 0xffff) {
      result += String.fromCharCode(codePoint);
    } else {
      const adjusted = codePoint - 0x10000;

      result += String.fromCharCode(
        0xd800 + (adjusted >> 10),
        0xdc00 + (adjusted & 0x3ff)
      );
    }
  }

  return result;
}

function decodeBase64Utf8(value) {
  const alphabet =
    'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

  let encoded = String(value ?? '').replace(/\s/g, '');

  if (!encoded) {
    return '';
  }

  const firstPadding = encoded.indexOf('=');

  if (firstPadding !== -1) {
    const padding = encoded.slice(firstPadding);

    if (!/^={1,2}$/.test(padding)) {
      throw new Error('invalid Base64 padding');
    }

    encoded = encoded.slice(0, firstPadding);
  }

  if (/[^A-Za-z0-9+/]/.test(encoded)) {
    throw new Error('invalid Base64 character');
  }

  if (encoded.length % 4 === 1) {
    throw new Error('invalid Base64 length');
  }

  const bytes = [];

  for (let i = 0; i < encoded.length; i += 4) {
    const first = alphabet.indexOf(encoded[i]);
    const second = alphabet.indexOf(encoded[i + 1]);

    const third =
      i + 2 < encoded.length
        ? alphabet.indexOf(encoded[i + 2])
        : -1;

    const fourth =
      i + 3 < encoded.length
        ? alphabet.indexOf(encoded[i + 3])
        : -1;

    if (first < 0 || second < 0) {
      throw new Error('invalid Base64 quartet');
    }

    bytes.push((first << 2) | (second >> 4));

    if (third >= 0) {
      bytes.push(((second & 15) << 4) | (third >> 2));
    }

    if (fourth >= 0) {
      bytes.push(((third & 3) << 6) | fourth);
    }
  }

  return decodeUtf8(bytes);
}

