const iterationResults = Array.isArray(iterations) ? iterations : [];

for (let i = 0; i < requestedFiles.length; i++) {
  const path = String(requestedFiles[i]?.path ?? '').trim();

  const outputs = Array.isArray(iterationResults[i])
    ? iterationResults[i]
    : [];

  const apiOutput = outputs.find(
    (item) =>
      item &&
      typeof item === 'object' &&
      Object.prototype.hasOwnProperty.call(item, 'data')
  );

  const data = apiOutput?.data;

  if (!data || data.type !== 'file' || !data.sha) {
    errors.push(`cannot read repository context: ${path}`);
    continue;
  }

  let content;

  try {
    content = decodeBase64Utf8(data.content);
  } catch (error) {
    errors.push(
      `cannot decode repository context: ${path}: ${String(
        error?.message ?? error
      )}`
    );
    continue;
  }

  if (content.length > 20000) {
    errors.push(`context file too large: ${path}`);
    continue;
  }

  totalChars += content.length;

  files.push({
    path,
    sha: String(data.sha),
    content
  });
}

if (totalChars > 30000) {
  errors.push('repository context exceeds 30000 characters');
}

return {
  valid:
    errors.length === 0 &&
    files.length === requestedFiles.length,
  errors,
  files,
  count: files.length,
  total_chars: totalChars
};

const status = Number(<publishdevelopmentcontract.status>);
const valid = [200, 201, 204, 409].includes(status);
return {
