  artifact = raw;
  for (let attempt = 0; attempt < 2 && typeof artifact === 'string'; attempt += 1) {
    try {
      artifact = JSON.parse(artifact);
    } catch (_) {
      errors.push('Артефакт архитектуры не является валидным JSON');
      artifact = null;
      break;
    }
  }
  if (artifact?.data && typeof artifact.data === 'object' && !Array.isArray(artifact.data)) {
    artifact = artifact.data;
  }
  if (!artifact || typeof artifact !== 'object' || Array.isArray(artifact)) {
    errors.push('Артефакт архитектуры не является JSON-объектом');
    artifact = null;
  }
}

