function normalizeForComparison(value) {
  if (Array.isArray(value)) {
    return value.map(normalizeForComparison);
  }

  if (value && typeof value === 'object') {
    const result = {};

    for (const key of Object.keys(value).sort()) {
      result[key] = normalizeForComparison(value[key]);
    }

    return result;
  }

  return value;
}

function valuesEqual(left, right) {
  return JSON.stringify(normalizeForComparison(left)) ===
    JSON.stringify(normalizeForComparison(right));
}

if (artifact) {
  if (artifact.schema_version !== '2.0') {
    errors.push('Неподдерживаемая schema_version');
  }

  if (artifact.workflow_id !== '02-architecture') {
    errors.push('Неверный workflow_id');
  }

  if (artifact.status !== 'approved') {
    errors.push('Архитектура не approved');
  }

  if (artifact.review?.passed !== true) {
    errors.push('Architecture Reviewer не вернул passed=true');
  }

  if (artifact.approval?.decision !== 'approve') {
    errors.push('Нет человеческого решения approve');
  }

  const repositoryKey = `${artifact.owner}/${artifact.repo}`;

  if (!allowedRepositories.has(repositoryKey)) {
    errors.push(`Repository отсутствует в allowlist: ${repositoryKey}`);
  }

  if (!allowedBaseBranches.has(String(artifact.base_branch ?? ''))) {
    errors.push(
      `Base branch отсутствует в allowlist: ${artifact.base_branch}`
    );
  }

  if (!Array.isArray(artifact.repository_plan?.files)) {
    errors.push('Нет repository_plan.files');
  }

  if (String(artifact.architecture ?? '').trim().length < 100) {
    errors.push('Architecture отсутствует или слишком короткая');
  }

  const profile = artifact.implementation_profile;

  if (!profile || typeof profile !== 'object' || Array.isArray(profile)) {
    errors.push('Нет implementation_profile');
  } else {
    const canonical = catalogProfiles.find(
      (item) =>
        item &&
        typeof item === 'object' &&
        String(item.profile_id ?? '') ===
          String(profile.profile_id ?? '')
    );

    if (!canonical) {
      errors.push(
        `Implementation profile отсутствует в доверенном каталоге: ` +
        `${String(profile.profile_id ?? '')}`
      );
    } else {
      const repositoryKey = `${String(artifact.owner ?? '')}/` +
        `${String(artifact.repo ?? '')}`;
      const profileRepositories = Array.isArray(
        canonical.allowed_repositories
      )
        ? canonical.allowed_repositories.map((item) => String(item ?? ''))
        : [];

      if (!profileRepositories.includes(repositoryKey)) {
        errors.push(
          `Профиль ${canonical.profile_id} не разрешён для ` +
          `репозитория ${repositoryKey}`
        );
      }

      // Сравниваются все канонические поля профиля, включая capabilities,
      // required_files, build и limits. selection_reason может быть дополнительным.
      for (const key of Object.keys(canonical)) {
        if (!valuesEqual(profile[key], canonical[key])) {
          errors.push(
            `Поле implementation_profile.${key} ` +
            'не совпадает с доверенным каталогом'
          );
        }
      }

      if (
        String(profile.catalog_version ?? '') !== catalogVersion
      ) {
        errors.push(
          'Версия каталога implementation profile не совпадает'
        );
      }
    }
  }
}

const runId = String(artifact?.run_id ?? '');

if (!/^run-\d{8}-\d{6}-[a-z0-9]{6}$/.test(runId)) {
  errors.push('Некорректный run_id');
}

const branch = `ai/${runId}`;

return {
  valid: errors.length === 0,
  errors,
  artifact,
  run_id: runId,
  owner: String(artifact?.owner ?? ''),
  repo: String(artifact?.repo ?? ''),
  base_branch: String(artifact?.base_branch ?? ''),
  branch,
  branch_encoded: encodeURIComponent(branch),
  dry_run: Boolean(<start.dry_run>),
  developer_revision_comments: String(<start.developer_revision_comments> ?? '').trim(),
  artifact_ref: {
    owner: String(<start.artifact_owner> ?? ''),
    package: String(<start.artifact_package> ?? ''),
    version: String(<start.artifact_version> ?? ''),
    file: String(<start.architecture_file> ?? '')
  }
};

const artifact = <validateimplementationinput.result.artifact>;
const tree = <getrepositorytree.data>;
const entries = Array.isArray(tree?.tree) ? tree.tree : [];
const profile = artifact?.implementation_profile ?? {};
const planFiles = Array.isArray(artifact?.repository_plan?.files)
  ? artifact.repository_plan.files
  : [];

const errors = [];

if (tree?.truncated === true) {
  errors.push(
    'Gitea tree truncated; repository context нельзя считать полным'
  );
}

const existing = new Map(
  entries.map((entry) => [String(entry.path ?? ''), entry])
);

const protectedPrefixes = [
  '.git/',
  '.gitea/',
  '.github/',
  'ci/',
  'k8s/',
  'policies/',
  'secrets/',
  'vendor/',
  'node_modules/',
  'dist/',
  'build/',
  'artifacts/'
];

const binaryExtensions =
  /\.(png|jpe?g|gif|webp|bmp|pdf|zip|tar|gz|7z|exe|dll|so|dylib|ico|woff2?|ttf|eot|class|jar|pyc)$/i;

const maxContextFiles = Number(
  profile?.limits?.max_context_files ?? 50
);

const selected = [];
const seen = new Set();

function isProtected(path) {
  const lower = path.toLowerCase();
  return protectedPrefixes.some((prefix) =>
    lower.startsWith(prefix)
  );
}

function addExistingTextFile(path, source) {
  const normalized = String(path ?? '').trim();

  if (!normalized || seen.has(normalized)) {
    return;
  }

  if (isProtected(normalized) || binaryExtensions.test(normalized)) {
    return;
  }

  const entry = existing.get(normalized);

  if (!entry || entry.type !== 'blob') {
    return;
  }

  seen.add(normalized);
  selected.push({
    path: normalized,
    encoded_path: normalized
      .split('/')
      .map(encodeURIComponent)
      .join('/'),
    sha: String(entry.sha ?? entry.id ?? ''),
    source
  });
}

// Приоритет 1: все planned files, которые уже существуют.
for (const file of planFiles) {
  addExistingTextFile(file?.path, 'repository_plan');
}

// Приоритет 2: manifests и общие context files доверенного профиля.
for (const path of Array.isArray(profile?.context_files)
  ? profile.context_files
  : []) {
  addExistingTextFile(path, 'implementation_profile');
}

// Приоритет 3: существующие текстовые файлы внутри разрешённых context roots.
const contextRoots = Array.isArray(profile?.context_roots)
  ? profile.context_roots
      .map((root) => String(root ?? '').replace(/\/+$/, ''))
      .filter(Boolean)
  : [];

const sortedEntries = [...entries].sort((left, right) =>
  String(left?.path ?? '').localeCompare(String(right?.path ?? ''))
);

for (const entry of sortedEntries) {
  const path = String(entry?.path ?? '');

  const belongsToContextRoot = contextRoots.some(
    (root) => path === root || path.startsWith(`${root}/`)
  );

  if (belongsToContextRoot) {
    addExistingTextFile(path, 'context_root');
  }
}

if (selected.length > maxContextFiles) {
  errors.push(
    `Для чтения требуется ${selected.length} файлов, ` +
    `но profile разрешает максимум ${maxContextFiles}. ` +
    'Нужно увеличить лимит профиля или уменьшить область реализации.'
  );
}

const paths = selected.slice(0, maxContextFiles);

return {
  valid: errors.length === 0,
  errors,
  paths,
  selected_count: selected.length,
  max_context_files: maxContextFiles,
  tree_entries: entries.map((entry) => ({
    path: String(entry?.path ?? ''),
    type: String(entry?.type ?? ''),
    sha: String(entry?.sha ?? entry?.id ?? '')
  })),
  base_sha: <getbasebranch.data.commit.id>
};

const listed = <gettargetbranch.data>;
const expectedName = String(<validateimplementationinput.result.branch> ?? '');
const existingBranch = Array.isArray(listed)
  ? listed.find((item) => String(item?.name ?? '') === expectedName)
  : null;
const existing = Boolean(existingBranch);
const selected = existing ? existingBranch : <getcreatedbranch.data>;
const status = existing ? Number(<gettargetbranch.status>) : Number(<getcreatedbranch.status>);
const actualName = String(selected?.name ?? '');
const commitSha = String(selected?.commit?.id ?? '');
return {
  valid: status === 200 && expectedName.length > 0 && actualName === expectedName && /^[0-9a-f]{40}$/i.test(commitSha),
  existing,
  branch: actualName,
  commit_sha: commitSha,
  status
};

const status = Number(<triggerworkflow03revision.status>);
if (![200, 202].includes(status)) throw new Error(`Новая редакция Workflow 03 не поставлена в очередь: HTTP ${status}`);
return {valid: true, status};

const draft = <buildcoderevisionresponse.result>;
return {
  status: 'revision_queued',
  run_id: draft.run_id,
  artifact_ref: draft.artifact_ref,
  next_execution_http_status: Number(<triggerworkflow03revision.status>)
};

const existing = Array.isArray(<findexistingpr.data>) ? <findexistingpr.data>[0] : null;
const created = <createpr.data>;
const pr = existing && Number(existing.number) > 0 ? existing : created;
const number = Number(pr?.number ?? 0);
if (!Number.isInteger(number) || number < 1) throw new Error('Не удалось создать или найти PR.');
return {
  existing: Boolean(existing && Number(existing.number) > 0),
  number,
  html_url: String(pr?.html_url ?? ''),
  head_sha: String(pr?.head?.sha ?? '')
};
